import { Component } from '@angular/core';

@Component({
  selector: 'app-ejercicio19',
  templateUrl: './ejercicio19.component.html',
  styleUrls: ['./ejercicio19.component.css']
})
export class Ejercicio19Component {



}
<div class="input-group mb-3">
  <input type="text" class="form-control" placeholder="Nombre del producto" [(ngModel)]="productName" (keyup.enter)="sendProductName()">
  <div class="input-group-append">
    <button class="btn btn-outline-secondary" type="button" (click)="sendProductName()">Buscar</button>
  </div>
</div>
